parameters.jsCode:
const item = $input.item;
const output = item.json.output ?? {};

if (typeof output.ticket_number === 'string') {
  output.ticket_number = output.ticket_number.trim().toUpperCase();
}

if (typeof output.pole_number === 'string') {
  output.pole_number = output.pole_number.trim().toUpperCase();
}

return item;

const output = $input.item.json.output;

const ticket_number = output.ticket_number;
const pole_number = output.pole_number;

let lookup_type;

if (ticket_number && pole_number) {
  lookup_type = 'both';
} else if (ticket_number) {
  lookup_type = 'ticket_only'
} else {
  lookup_type = 'pole_only'
}
return {
  json: {
    ...output,
    lookup_type
  }
}

const email = $input.first().json;

return {
  json: {
    subject: email.subject,
    name: email.from?.value?.[0]?.name,
    email: email.from?.value?.[0]?.address,
    body: email.text?.replace(/\s+/g, ' ').trim()
  }
};

